float3 mus;
float2 rs, uv1, uv6, uv7, uv8;
float dx,dy;
shader_body {
uv = uv_orig;
uv1 = (uv-.5) * aspect.xy;

//BACKGROUND
float z = 16*length(uv1)+time;
float2 uvn =normalize(uv1);
rs = clamp(tan(z)*uvn,-5,5)/2;

//CRYSTAL
float mult = q31;
uv7 = sin(uv1*mult);
uv8 = uv7;
float dist = length(uv8);
dist *= (abs(uv1.x) + abs(uv1.y))+ q32;

float ang2 = atan2 (uv8.y,uv8.x);
ang2 =  .1*floor (16* ang2);
float2 dir = .5*uv8+float2 (cos(ang2), sin(ang2));


z = (1-cos(8*dist));
z = saturate (z);

//ADD
float mask = (z >= .5); //momentan beliebig
rs = q28*rs + (1-q28)*rs.yx;
uv += (1-mask)*.03*(rs.yx) + .5*mask*z*normalize(dir);



//DOTS
float2 uv2 = .7*uv1+.3*sin(uv1*16+4*float2 (q5,q6));
uv2 *= .2;
float3 dots = q26*saturate(.001/(length(uv2)));
float3 blur = GetBlur1(frac(uv));
float3 crisp= GetPixel(uv);
float3 diff = (crisp) - .5*blur;
float3 ret1 = crisp + mus + dots;

float3 mod = tex2D (sampler_noise_lq,.5*uv+time*.01)-.2;
mod = 1 - mod*diff;

ret = (1-mask)*ret1*mod + mask*ret1*mod;
ret = ret *.98- .03;

}

#define sat saturate
sampler sampler_pw_noise_lq;
float mask1, gmask, bsize, rad1, slot, grid, anz, bcentre;
float glow, tmp, lamp, dist, bdist, b2dist, dist_c, smask, z;
float2 rs, rs0, uv0, uv1, uv2, uv3,uv4, rsk, bubble, dz;
float3 noise, bubbles;

static const float2 pix = texsize.zw, center = float2 (q1,q2);
static const float3 CamPos = float3(q4,q5,q6);
static const float myzoom = q7;
static const float3x3 RotMat = float3x3(q20,q21,q22,q23,q24,q25,q26,q27,q28);
static const float3 col_struc =  float3(1,.4,.1)/4;

float3 GetBlurX (float2 uvi, float x) {return lerp (GetPixel(uvi), GetBlur1(uvi), x);}
float GetDist(float2 uvi)   {return 1-GetPixel(uvi).b;}
float GetDistB(float2 uvi)  {return 1-GetBlur1(uvi).b;}
float GetDistB2(float2 uvi) {return 1-GetBlur2(uvi).b;}

float MinDistB (float2 uvi) {float tmp; float4 nb; //##nicht ideal
  tmp = GetDist(uvi);
  return min(tmp,GetDistB(uvi)) ;}

float shadow (float2 uvi) {int n; float dark; float2 uvc, dx;
  dark = 0; n = 1;
  while ( (n <= 2)) 
     {dx = .04*n * (center-.5); 
      uvc = (uvi+dx); 
      dark = dark + sat(4*(GetBlur1(uvi).b-GetBlur1(uvc).b) -dx*4); 
      n++;}
  return (dark/2);}

shader_body {
uv = (uv-.5)*.9 + .5;
uv0 = uv;

dist = MinDistB(uv);
bdist = lerp(dist,GetDistB(uv),.2);
float focus = sat(abs(GetDistB(uv)-dist_c)*3);

float2 noise = tex2D (sampler_noise_mq,float2(uv.x,uv.y/4-.1*time)).xy;
uv += .004*bdist*noise ;
float2 uv5 = (uv-.5)*aspect.xy  - float2(q11,q12);
bubbles = 0; gmask = 0; anz = 3; bcentre = 0;
for (int m= 1; m<= anz; m++)
{
  z = 1-frac(1.0/anz*m+q9); 
  uv1 = uv5*z;
//  uv1 = mul(uv1, float2x2(.7,.7,-.7,.7));

  grid = 16.0*m/512;

  slot = tex2D(sampler_pw_noise_lq,uv1.x*grid)+.5;
  uv1.y += slot*time*.06;
  bsize = tex2D(sampler_pw_noise_lq,uv1*grid);
  rsk = frac(8*m*uv1)-.5 ;
  dz = normalize(rsk);
  rad1 = 3*length (rsk) *(2+m);
  uv4 =  (rad1*rad1)*dz;
  mask1 = saturate(9-8*rad1) * (bsize > .85) ;
  gmask = gmask || mask1;
  bubbles += float3 (uv4,.1/(rad1)) * (1-z) * mask1;
}
gmask *= sat (bdist*16-8*z);
uv +=  .1*bubbles*gmask;

dist = MinDistB(uv);
bdist = lerp(dist,GetDistB(uv),.2);
dist_c = clamp(GetDistB2 (center),.1,.4); //center distance

float struc = GetBlurX(uv,focus).r;

ret = struc* col_struc *float3(1-bdist,1,1)+ pow(sat(struc),4) * float3 (0,1,.2);
float4 noise9 = tex3D(sampler_noisevol_hq, 
                      ((uv.xyy*q28
                       )*texsize.xyy*texsize_noisevol_hq.zww
                      ).xyz*
                      float3(1,1,0)*0.05 + 
                      time*float3(0,0,1)*q31
                     );
if(ret.x> q26*q13         && ret.x<= q23*q11        )ret.z -= (noise9).x*.5; 
if(ret.y> q25*q11         && ret.y<= q22*q12        )ret.x -= (noise9).y*.5; 
if(ret.z> q24*q12         && ret.z<= q21*q13        )ret.y -= (noise9).z*.5; 


//distant light
ret += gmask*bubbles.z * (1+slow_roam_cos);

ret = lerp(ret, float3(0,.05,.1)*4*q19, sat(pow(bdist,1.5)));

float moon = (.5/length(sin(3*(uv5))));
ret += sat(MinDistB(uv)*6-5)*moon*float3(0,.1,.1);

//Lamp
uv3 = uv-center; 
float ddd = GetPixel(uv).r - GetPixel((uv-.5)*(1.01)+.5).r;
lamp = saturate(1-4*length(uv3)) * (.1+struc+ddd);
ret += lamp*(saturate(1-bdist/2))*(1-0*shadow(uv)) * float3(1,.8,.3);

ret = 1-exp((-1.6)*ret);
//ret += shadow(uv);
//ret = GetPixel(uv0).r;
}

